import compact from './compact';
import isNullOrUndefined from './isNullOrUndefined';
import isObject from './isObject';
import isUndefined from './isUndefined';

export default <T>(
  object: T,
  path?: string | null,
  defaultValue?: unknown,
): any => {
  if (path === 'job_title') {
    console.log(object, defaultValue, 'Intial value');
  }
  // Safari : {job_title: null} , null
  // Chrome: {job_title : _f { mount..}} null

  if (!path || !isObject(object)) {
    return defaultValue;
  }

  const result = compact(path.split(/[,[\].]+?/)).reduce(
    (result, key) =>
      isNullOrUndefined(result) ? result : result[key as keyof {}],
    object,
  );

  if (path === 'job_title') {
    console.log(
      result,
      isNullOrUndefined(result),
      result === object,
      object[path as keyof T],
      'Final value',
    );
  }

  return isUndefined(result) || result === object
    ? isUndefined(object[path as keyof T])
      ? defaultValue
      : object[path as keyof T]
    : result;
};
